cases = [
    (1, 'odd'), (2, 'even'), (3, 'odd'), (4, 'even'), (0, 'even'),
]

def check_odd_even(n):
    return 'odd' if n % 2 != 0 else 'even'

for value, expected in cases:
    result = check_odd_even(value)
    status = 'PASSED' if result == expected else 'FAILED'
    print(f'test_check_odd_even[{value}-{expected}] {status}')

print(f'{len(cases)} passed')
